/* 由 tools/make_samples.js 生成：内置实验例程 */
window.SHYL_SAMPLES = [{"id":"exam","name":"考试综合模板（8253+8259+8255+0832+0809）","note":"默认接线即可运行。6 位数码管显示 B B C C D D，PB 上的 LED 每 2 秒多亮一个，DAC 每 2 秒换一档电压。","wiring":{},"source":"﻿;=====================================================================\r\n; 微机接口考试  综合模板（单文件）\r\n;   8253 + 8259 + 8255 + DAC0832 + ADC0809\r\n;   所有实验用到的硬件初始化都写进来；用不到的直接不调用/不接线即可\r\n;---------------------------------------------------------------------\r\n; 默认固定接线（考试按这套接，代码不用改）：\r\n;\r\n;   8255：方式0，PA/PB/PC 全部输出（80H）\r\n;     /CS -> CS1（210H~213H）\r\n;     PA0~PA7 -> 数码管段码总线 LEDB；做点阵时 -> 行 R1~R8\r\n;     PB0~PB7 -> 8 个 LED（高电平点亮）；做点阵时 -> 列 C1~C8\r\n;     PC0~PC5 -> 6 位数码管位选 BIT（PC0 最右，PC5 最左）\r\n;\r\n;   6 位数码管：最右位地址最小，对应 PC0 和 DISP_BUF[0]；\r\n;                最左位对应 PC5 和 DISP_BUF[5]。\r\n;\r\n;   8253：\r\n;     /CS -> CS0（200H~20FH）\r\n;     1MHz -> CLK0；GATE0 -> +5V\r\n;     OUT0 -> 8259 IRQ0\r\n;     级联时：OUT0 -> CLK1，OUT1 -> CLK2；GATE1/GATE2 -> +5V\r\n;\r\n;   8259：\r\n;     /CS -> CS3（230H~23FH）\r\n;     CPU INTR -> 8259 INT；CPU INTA -> 8259 INTA\r\n;     IRQ0 <- 8253 OUT0\r\n;     IRQ1 <- 0809 EOC/INT\r\n;     IRQ2 <- AN2 单脉冲（按键）\r\n;\r\n;   0832：\r\n;     /CS -> 250H 译码输出\r\n;     Uref -> +5V；DAOUT -> 万用表/示波器\r\n;\r\n;   0809：\r\n;     /CS -> 260H 译码输出；CLK -> 500kHz\r\n;     IN0 <- 0~5V 电位器中心抽头\r\n;     EOC/INT -> 8259 IRQ1\r\n;\r\n;   公共：所有芯片共地；数码管按共阴、段高有效、位选高有效；\r\n;         LED 按高电平点亮。考场极性相反时，只改下面的 INVERT 常量。\r\n;---------------------------------------------------------------------\r\n; 默认程序在跑：\r\n;   1ms 中断：0.1s 启动一次 ADC；1s 计数 0~20；1.5s 倒计时 15~0；\r\n;             0.1s 计数 0~60；2s 逐个点 LED，同时 0832 换一个电压\r\n;   IRQ1：读 ADC，按电压显示 U x.x\r\n;   IRQ2：按键计数（默认屏蔽）\r\n;   主循环：数码管动态扫描\r\n;---------------------------------------------------------------------\r\n; 注意：\r\n;   点阵用 PA/PB，数码管用 PA/PC，PA 共用，不能同时跑；\r\n;   跑点阵时把 MAIN 改成 JMP MATRIX_DEMO，并去掉 ISR0 里的 CALL LED_NEXT\r\n;   （PB 已被点阵列占用）。\r\n;   默认 6 位从左到右：B B C C D D，即 [5][4]=B，[3][2]=C，[1][0]=D。\r\n;   显示缓冲和位选一一对应：\r\n;       DISP_BUF[0] -> PC0 -> 最右位（地址最小）\r\n;       DISP_BUF[1] -> PC1 -> 右数第 2 位\r\n;       DISP_BUF[2] -> PC2 -> 右数第 3 位\r\n;       DISP_BUF[3] -> PC3 -> 右数第 4 位\r\n;       DISP_BUF[4] -> PC4 -> 右数第 5 位\r\n;       DISP_BUF[5] -> PC5 -> 最左位\r\n;   所以两位数的十位要写在比个位更大的下标里。\r\n;   按键显示占第 3 位；做按键题时关掉 C 或改 ISR2 里的 DI。\r\n;   ADC 电压显示占满 6 位（U 在第 5 位，q.s 在第 1、0 位）；\r\n;   做 ADC 题时只保留 ADC 显示，关掉 B/C/D。\r\n;   8253 的 2s、5s 级联初始化已经写好，默认不调用，题目要方波/脉冲时再 CALL。\r\n;---------------------------------------------------------------------\r\n; 考试时只改：\r\n;   1. IRQ_MASK：只开定时=0FEH；定时+ADC=0FCH；定时+按键=0FAH；\r\n;      定时+ADC+按键=0F8H\r\n;   2. T_A/T_B/T_C/T_D/T_ADC：周期，单位 ms\r\n;   3. ISR0/ISR1/ISR2 里各任务的计数上限、显示位置、输出口\r\n;   4. 要跑点阵：把 MAIN 的 JMP MAIN 改成 JMP MATRIX_DEMO\r\n;=====================================================================\r\n\r\n        .8086\r\n        .MODEL SMALL\r\n        .STACK 100H\r\n\r\n;=====================================================================\r\n; 一、端口与参数\r\n;=====================================================================\r\n;---- 8253：三个计数器 + 控制口 ----\r\nP8253_C0        EQU     0200H           ; 计数器0：1kHz 定时\r\nP8253_C1        EQU     0201H           ; 计数器1：级联/2s 方波\r\nP8253_C2        EQU     0202H           ; 计数器2：级联/5s 脉冲\r\nP8253_CTRL      EQU     0203H           ; 控制字\r\n\r\n;---- 8255：PA=段码/行，PB=LED/列，PC=位选 ----\r\nP8255_PA        EQU     0210H\r\nP8255_PB        EQU     0211H\r\nP8255_PC        EQU     0212H\r\nP8255_CTRL      EQU     0213H\r\n\r\n;---- 8259：偶地址写 ICW1/OCW2/OCW3，奇地址写 ICW2~4/OCW1 ----\r\nP8259_0         EQU     0230H\r\nP8259_1         EQU     0231H\r\n\r\nDAC_PORT        EQU     0250H           ; 0832 片选\r\nADC_PORT        EQU     0260H           ; 0809 片选\r\n\r\n;---- 中断类型号：ICW2=08H，所以 IRQn 对应 08H+n ----\r\nIRQ0_VECT       EQU     08H\r\nIRQ1_VECT       EQU     09H\r\nIRQ2_VECT       EQU     0AH\r\n\r\n;---- 默认只开 IRQ0；用 ADC 改 0FCH；只加按键改 0FAH；三者全开 0F8H ----\r\nIRQ_MASK        EQU     0FEH\r\n\r\n;---- 定时常数：1kHz 中断，单位 ms ----\r\nT_A             EQU     2000\r\nT_B             EQU     1000\r\nT_C             EQU     1500\r\nT_D             EQU     100\r\nT_ADC           EQU     100\r\n\r\n;---- 点阵 ----\r\nFRAMES_PER_CHAR EQU     225\r\nCHARS           EQU     4\r\nROW_INVERT      EQU     0\r\nCOL_INVERT      EQU     0\r\n\r\n;---- 数码管、LED ----\r\nSEG_INVERT      EQU     0\r\nDIG_INVERT      EQU     0\r\nDISP_DELAY      EQU     120\r\nLED_INVERT      EQU     0\r\n\r\n        .DATA\r\n;---- 七段码 0~9、A~F ----\r\n;---- 共阴七段码：0~9、A~F；段序 a,b,c,d,e,f,g,dp，1=亮 ----\r\nSEG_TAB DB      3FH,06H,5BH,4FH,66H,6DH,7DH,07H,7FH,6FH\r\n        DB      77H,7CH,39H,5EH,79H,71H\r\n\r\n; 6 位显示缓冲：[0]=最右（地址最小），[5]=最左\r\n; 缓冲里存的是段码，不是数字；SHOW2/SHOW1 负责把数字翻成段码\r\nDISP_BUF DB     0,0,0,0,0,0\r\nDISP_IDX DB     0\r\n\r\n;---- 1ms 计数：TICK1MS 给 WAIT_1MS 判断是否走过 1ms ----\r\nTICK1MS DW      0\r\nT_A_CNT DW      0                       ; 任务A 软件分频，2s\r\nT_B_CNT DW      0                       ; 任务B 软件分频，1s\r\nT_C_CNT DW      0                       ; 任务C 软件分频，1.5s\r\nT_D_CNT DW      0                       ; 任务D 软件分频，0.1s\r\nT_ADC_CNT DW    0                       ; ADC 启动分频，0.1s\r\n\r\n;---- 各任务当前值 ----\r\nCNT_B   DB      0                       ; 0~20\r\nCNT_C   DB      15                      ; 15~0\r\nCNT_D   DB      0                       ; 0~60\r\nLED_N   DB      0                       ; 已点亮 LED 个数 0~8\r\nKEY_CNT DB      0                       ; 按键计数 0~9\r\nADC_VAL DB      0                       ; 0809 读回的数字量\r\nDAC_IDX DB      0FFH                    ; DAC 表索引，FFH 使下一次从 0 开始\r\n\r\n;---- 0832 输出电压对应的数字量：1.0、2.0、3.0、4.0、4.5V ----\r\n; 公式 N=(U+5)*256/10（Uref=+5V，双极性）\r\nDAC_TAB DB      154,179,205,230,243\r\n\r\n;---- 0~8 个 LED 的图案：1 个亮、2 个亮……8 个全亮 ----\r\nLED_TAB DB      00H,01H,03H,07H,0FH,1FH,3FH,7FH,0FFH\r\n\r\n;---- 点阵字模：“接口技术”四个字，每字 8 列，每列 1 字节 ----\r\nFONT    DB      022H,0FFH,052H,076H,023H,072H,052H,08AH\r\n        DB      000H,000H,07EH,042H,042H,07EH,000H,000H\r\n        DB      022H,072H,027H,0FAH,056H,023H,052H,08AH\r\n        DB      008H,028H,07FH,008H,01CH,02AH,049H,008H\r\n\r\n        .CODE\r\n;=====================================================================\r\n; 二、主程序：全部初始化 -> 开中断 -> 扫描\r\n;=====================================================================\r\nSTART:\r\n        MOV     AX, @DATA\r\n        MOV     DS, AX\r\n\r\n        ;---- 初始化顺序：8255 定方向 -> 8253 出 1kHz -> 8259 收中断 ----\r\n        ; 先 CLI，避免初始化中途被旧中断打断\r\n        CLI\r\n        CALL    INIT_8255\r\n        CALL    CLEAR_BUF\r\n        CALL    INIT_8253_1KHZ\r\n        CALL    INIT_8259\r\n        CALL    INSTALL_VECTS\r\n\r\n        ;---- 显示初值：B 在最左两位，C 在中间，D 在最右两位 ----\r\n        ; SHOW2 的 DI 是个位（右位），十位自动写到 DI+1\r\n        MOV     DI, 4\r\n        MOV     AL, CNT_B\r\n        CALL    SHOW2\r\n        MOV     DI, 2\r\n        MOV     AL, CNT_C\r\n        CALL    SHOW2\r\n        MOV     DI, 0\r\n        MOV     AL, CNT_D\r\n        CALL    SHOW2\r\n\r\n        ;---- LED 全灭，DAC 先输出 0 ----\r\n        MOV     DX, P8255_PB\r\n        XOR     AL, AL\r\n        OUT     DX, AL\r\n        MOV     DX, DAC_PORT\r\n        OUT     DX, AL\r\n\r\n        CALL    ENABLE_IRQ\r\n        STI\r\n\r\nMAIN:\r\n        CALL    DISP_SCAN\r\n        JMP     MAIN\r\n\r\n;=====================================================================\r\n; 三、初始化模块\r\n;=====================================================================\r\n; 8255：方式0，PA/PB/PC 全部输出\r\n; 80H = 1000 0000B：\r\n;   D7=1 方式0置位；D6D5=00 A组方式0；D4=0 PA输出；\r\n;   D3=0 PC高4位输出；D2=0 B组方式0；D1=0 PB输出；D0=0 PC低4位输出\r\nINIT_8255 PROC\r\n        MOV     DX, P8255_CTRL\r\n        MOV     AL, 80H\r\n        OUT     DX, AL\r\n\r\n        ; 三口先清 0，上电不要让数码管/LED 乱亮\r\n        MOV     DX, P8255_PA\r\n        XOR     AL, AL\r\n        OUT     DX, AL\r\n        MOV     DX, P8255_PB\r\n        OUT     DX, AL\r\n        MOV     DX, P8255_PC\r\n        OUT     DX, AL\r\n        RET\r\nINIT_8255 ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; 8255：A/B 输出、C 输入（89H），做查询/点阵需要 PC7 输入时用\r\n; 89H = 1000 1001B：A/B 输出，C 高 4 位和低 4 位都输入\r\nINIT_8255_89 PROC\r\n        MOV     DX, P8255_CTRL\r\n        MOV     AL, 89H\r\n        OUT     DX, AL\r\n\r\n        MOV     DX, P8255_PA\r\n        XOR     AL, AL\r\n        OUT     DX, AL\r\n        MOV     DX, P8255_PB\r\n        OUT     DX, AL\r\n        RET\r\nINIT_8255_89 ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; 8253：计数器0，方式3，1MHz/1000 = 1kHz，OUT0 -> 8259 IRQ0\r\n; 36H = 00 11 011 0B：\r\n;   D7D6=00 选计数器0；D5D4=11 先写低字节再写高字节；\r\n;   D3D2D1=011 方式3 方波；D0=0 二进制计数\r\nINIT_8253_1KHZ PROC\r\n        MOV     DX, P8253_CTRL\r\n        MOV     AL, 36H\r\n        OUT     DX, AL\r\n\r\n        ; 先写低字节，再写高字节；1000 = 03E8H\r\n        MOV     DX, P8253_C0\r\n        MOV     AX, 1000\r\n        OUT     DX, AL\r\n        MOV     AL, AH\r\n        OUT     DX, AL\r\n        RET\r\nINIT_8253_1KHZ ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; 8253 级联：OUT0(1kHz) -> CLK1，计数器1 方式3，初值2000 -> 2s 方波\r\nINIT_8253_2S PROC\r\n        CALL    INIT_8253_1KHZ\r\n\r\n        MOV     DX, P8253_CTRL\r\n        MOV     AL, 76H              ; 01 11 011 0：计数器1、方式3、先低后高\r\n        OUT     DX, AL\r\n        MOV     DX, P8253_C1\r\n        MOV     AX, 2000             ; 1kHz / 2000 = 0.5Hz，2s 方波\r\n        OUT     DX, AL\r\n        MOV     AL, AH\r\n        OUT     DX, AL\r\n        RET\r\nINIT_8253_2S ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; 8253 级联：计数器1 方式2 初值1000 -> 1Hz；\r\n;            计数器2 方式2 初值5 -> 5s，负脉冲宽度 1s\r\nINIT_8253_5S_1S PROC\r\n        CALL    INIT_8253_1KHZ\r\n\r\n        MOV     DX, P8253_CTRL\r\n        MOV     AL, 74H              ; 01 11 010 0：计数器1、方式2、先低后高\r\n        OUT     DX, AL\r\n        MOV     DX, P8253_C1\r\n        MOV     AX, 1000             ; 1kHz / 1000 = 1Hz\r\n        OUT     DX, AL\r\n        MOV     AL, AH\r\n        OUT     DX, AL\r\n\r\n        MOV     DX, P8253_CTRL\r\n        MOV     AL, 0B4H             ; 10 11 010 0：计数器2、方式2\r\n        OUT     DX, AL\r\n        MOV     DX, P8253_C2\r\n        MOV     AX, 5                ; 1Hz / 5 = 0.2Hz，周期 5s\r\n        OUT     DX, AL\r\n        MOV     AL, AH\r\n        OUT     DX, AL\r\n        RET\r\nINIT_8253_5S_1S ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; 8253 级联：计数器1 方式2 初值5000 -> 5s；\r\n;            计数器2 方式1 初值2000 -> 负脉冲宽度 2s\r\nINIT_8253_5S_2S PROC\r\n        CALL    INIT_8253_1KHZ\r\n\r\n        MOV     DX, P8253_CTRL\r\n        MOV     AL, 74H              ; 计数器1、方式2、先低后高\r\n        OUT     DX, AL\r\n        MOV     DX, P8253_C1\r\n        MOV     AX, 5000             ; 1kHz / 5000 = 0.2Hz，周期 5s\r\n        OUT     DX, AL\r\n        MOV     AL, AH\r\n        OUT     DX, AL\r\n\r\n        MOV     DX, P8253_CTRL\r\n        MOV     AL, 0B2H             ; 计数器2、方式1（可重触发单稳）\r\n        OUT     DX, AL\r\n        MOV     DX, P8253_C2\r\n        MOV     AX, 2000             ; 1kHz 下计 2000 = 2s 负脉冲\r\n        OUT     DX, AL\r\n        MOV     AL, AH\r\n        OUT     DX, AL\r\n        RET\r\nINIT_8253_5S_2S ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; 8259：单片、边沿、8086 模式；先全屏蔽\r\n; ICW1=13H：0001 0011B，边沿触发、单片、需要 ICW4\r\n; ICW2=08H：IRQ0~IRQ7 对应类型号 08H~0FH\r\n; ICW4=01H：8086 模式、普通 EOI、非缓冲\r\n; OCW1=FFH：先全屏蔽，初始化完再写 IRQ_MASK 放开\r\nINIT_8259 PROC\r\n        MOV     DX, P8259_0\r\n        MOV     AL, 13H\r\n        OUT     DX, AL\r\n\r\n        MOV     DX, P8259_1\r\n        MOV     AL, 08H\r\n        OUT     DX, AL\r\n        MOV     AL, 01H\r\n        OUT     DX, AL\r\n        MOV     AL, 0FFH\r\n        OUT     DX, AL\r\n        RET\r\nINIT_8259 ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; 开中断：OCW1 写允许掩码，0 = 允许\r\nENABLE_IRQ PROC\r\n        MOV     DX, P8259_1\r\n        MOV     AL, IRQ_MASK\r\n        OUT     DX, AL\r\n        RET\r\nENABLE_IRQ ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; 装一个中断向量：AX=ISR 偏移，DI=类型号*4\r\n; 实模式向量表在 0000:类型号*4：\r\n;   [DI]   = ISR 偏移\r\n;   [DI+2] = ISR 段地址（CS）\r\nINSTALL_VECT PROC\r\n        PUSH    BX\r\n        PUSH    ES\r\n        MOV     BX, AX\r\n        MOV     AX, 0\r\n        MOV     ES, AX\r\n        MOV     ES:[DI], BX\r\n        MOV     AX, CS\r\n        MOV     ES:[DI+2], AX\r\n        POP     ES\r\n        POP     BX\r\n        RET\r\nINSTALL_VECT ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; 一次装 IRQ0/IRQ1/IRQ2 三个向量\r\nINSTALL_VECTS PROC\r\n        MOV     DI, IRQ0_VECT*4\r\n        MOV     AX, OFFSET ISR0\r\n        CALL    INSTALL_VECT\r\n\r\n        MOV     DI, IRQ1_VECT*4\r\n        MOV     AX, OFFSET ISR1\r\n        CALL    INSTALL_VECT\r\n\r\n        MOV     DI, IRQ2_VECT*4\r\n        MOV     AX, OFFSET ISR2\r\n        CALL    INSTALL_VECT\r\n        RET\r\nINSTALL_VECTS ENDP\r\n\r\n;=====================================================================\r\n; 四、IRQ0：1ms 定时中断\r\n;   每个任务都是同一个套路：\r\n;     INC 软件计数器 -> CMP 周期 -> JB 下一个任务 -> 清零 -> 做事\r\n;   中断里只改显示缓冲/输出口，不在中断里做长延时\r\n;=====================================================================\r\nISR0 PROC  FAR\r\n        ; 保护现场：ISR 里用到的寄存器全部保存\r\n        PUSH    AX\r\n        PUSH    BX\r\n        PUSH    CX\r\n        PUSH    DX\r\n        PUSH    SI\r\n        PUSH    DI\r\n        PUSH    DS\r\n        MOV     AX, @DATA\r\n        MOV     DS, AX\r\n\r\n        ; 先发 EOI，否则 8259 认为当前中断没结束，后面不再响应\r\n        MOV     DX, P8259_0\r\n        MOV     AL, 20H\r\n        OUT     DX, AL\r\n\r\n        INC     TICK1MS             ; WAIT_1MS 靠这个变量判断 1ms\r\n\r\n;---- 每 100ms 启动一次 ADC（IRQ1 屏蔽时只启动不读）----\r\n        INC     T_ADC_CNT\r\n        CMP     T_ADC_CNT, T_ADC\r\n        JB      ISR0_D\r\n        MOV     T_ADC_CNT, 0\r\n        MOV     DX, ADC_PORT\r\n        XOR     AL, AL\r\n        OUT     DX, AL\r\n\r\n;---- D：0.1 秒，0~60 ----\r\nISR0_D:\r\n        INC     T_D_CNT\r\n        CMP     T_D_CNT, T_D\r\n        JB      ISR0_C\r\n        MOV     T_D_CNT, 0\r\n\r\n        INC     CNT_D\r\n        CMP     CNT_D, 61\r\n        JB      ISR0_SHOW_D\r\n        MOV     CNT_D, 0\r\nISR0_SHOW_D:\r\n        MOV     AL, CNT_D\r\n        MOV     DI, 0\r\n        CALL    SHOW2\r\n\r\n;---- C：1.5 秒，15~0 ----\r\nISR0_C:\r\n        INC     T_C_CNT\r\n        CMP     T_C_CNT, T_C\r\n        JB      ISR0_B\r\n        MOV     T_C_CNT, 0\r\n\r\n        DEC     CNT_C\r\n        JNS     ISR0_SHOW_C\r\n        MOV     CNT_C, 15\r\nISR0_SHOW_C:\r\n        MOV     AL, CNT_C\r\n        MOV     DI, 2\r\n        CALL    SHOW2\r\n\r\n;---- B：1 秒，0~20 ----\r\nISR0_B:\r\n        INC     T_B_CNT\r\n        CMP     T_B_CNT, T_B\r\n        JB      ISR0_A\r\n        MOV     T_B_CNT, 0\r\n\r\n        INC     CNT_B\r\n        CMP     CNT_B, 21\r\n        JB      ISR0_SHOW_B\r\n        MOV     CNT_B, 0\r\nISR0_SHOW_B:\r\n        MOV     AL, CNT_B\r\n        MOV     DI, 4\r\n        CALL    SHOW2\r\n\r\n;---- A：2 秒，逐个点亮 LED，同时 0832 换一个电压 ----\r\nISR0_A:\r\n        INC     T_A_CNT\r\n        CMP     T_A_CNT, T_A\r\n        JB      ISR0_OUT\r\n        MOV     T_A_CNT, 0\r\n\r\n        CALL    LED_NEXT\r\n        CALL    DAC_NEXT\r\n\r\nISR0_OUT:\r\n        POP     DS\r\n        POP     DI\r\n        POP     SI\r\n        POP     DX\r\n        POP     CX\r\n        POP     BX\r\n        POP     AX\r\n        IRET\r\nISR0 ENDP\r\n\r\n;=====================================================================\r\n; 五、IRQ1：0809 转换结束，读数字量并显示电压\r\n;   EOC 上升沿 -> IRQ1；ISR 里读 ADC_PORT 就是读转换结果\r\n;=====================================================================\r\nISR1 PROC  FAR\r\n        PUSH    AX\r\n        PUSH    BX\r\n        PUSH    CX\r\n        PUSH    DX\r\n        PUSH    SI\r\n        PUSH    DI\r\n        PUSH    DS\r\n        MOV     AX, @DATA\r\n        MOV     DS, AX\r\n\r\n        MOV     DX, P8259_0\r\n        MOV     AL, 20H\r\n        OUT     DX, AL\r\n\r\n        CLI                         ; 读/换算期间不让 IRQ0 抢进来改显示缓冲\r\n        MOV     DX, ADC_PORT\r\n        IN      AL, DX              ; 读回 0~255\r\n        MOV     ADC_VAL, AL\r\n        CALL    SHOW_VOLT           ; 换算成 q.s 并写显示缓冲\r\n\r\n        POP     DS\r\n        POP     DI\r\n        POP     SI\r\n        POP     DX\r\n        POP     CX\r\n        POP     BX\r\n        POP     AX\r\n        IRET\r\nISR1 ENDP\r\n\r\n;=====================================================================\r\n; 六、IRQ2：按键/外部脉冲，0~9 循环，显示在第 3 位\r\n;=====================================================================\r\nISR2 PROC  FAR\r\n        PUSH    AX\r\n        PUSH    BX\r\n        PUSH    CX\r\n        PUSH    DX\r\n        PUSH    SI\r\n        PUSH    DI\r\n        PUSH    DS\r\n        MOV     AX, @DATA\r\n        MOV     DS, AX\r\n\r\n        MOV     DX, P8259_0\r\n        MOV     AL, 20H\r\n        OUT     DX, AL\r\n\r\n        CLI\r\n        INC     KEY_CNT             ; 每来一个脉冲加 1\r\n        CMP     KEY_CNT, 10\r\n        JB      ISR2_SHOW\r\n        MOV     KEY_CNT, 0           ; 9 后回 0\r\nISR2_SHOW:\r\n        MOV     AL, KEY_CNT\r\n        MOV     DI, 3               ; 显示在第 3 位\r\n        CALL    SHOW1\r\n\r\n        POP     DS\r\n        POP     DI\r\n        POP     SI\r\n        POP     DX\r\n        POP     CX\r\n        POP     BX\r\n        POP     AX\r\n        IRET\r\nISR2 ENDP\r\n\r\n;=====================================================================\r\n; 七、DAC0832\r\n;   双极性公式：U = 2*Uref*N/256 - 5（Uref=+5V）\r\n;   反算：N = (U+5)*256/10\r\n;=====================================================================\r\n; AL = 数字量 N，直接输出；调用前先算好 N\r\nDAC_OUT PROC\r\n        MOV     DX, DAC_PORT\r\n        OUT     DX, AL\r\n        RET\r\nDAC_OUT ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; 表驱动：每次换下一个电压，1.0 -> 2.0 -> 3.0 -> 4.0 -> 4.5 -> 1.0\r\n; DAC_IDX 从 FFH 开始，第一次 INC 后变 0，先输出 1.0V\r\nDAC_NEXT PROC\r\n        PUSH    AX\r\n        PUSH    BX\r\n        PUSH    DX\r\n\r\n        MOV     AL, DAC_IDX\r\n        INC     AL\r\n        CMP     AL, 5               ; 0~4 共 5 个电压\r\n        JB      DAC_NEXT_OK\r\n        XOR     AL, AL              ; 4 之后回 0\r\nDAC_NEXT_OK:\r\n        MOV     DAC_IDX, AL\r\n\r\n        LEA     BX, DAC_TAB\r\n        XLAT                        ; AL = DAC_TAB[AL]\r\n        MOV     DX, DAC_PORT\r\n        OUT     DX, AL\r\n\r\n        POP     DX\r\n        POP     BX\r\n        POP     AX\r\n        RET\r\nDAC_NEXT ENDP\r\n\r\n;=====================================================================\r\n; 八、ADC0809\r\n;   写 ADC_PORT 时 D0~D2 是通道号，同时 START/ALE 有效，开始转换；\r\n;   转换结束 EOC 上升沿 -> IRQ1；也可以在查询方式里固定延时后读。\r\n;=====================================================================\r\n; AL = 通道号（0~7），写 ADC 端口即启动\r\nADC_START PROC\r\n        MOV     DX, ADC_PORT\r\n        OUT     DX, AL\r\n        RET\r\nADC_START ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; 查询方式读 ADC：启动后等 2ms，再读回；AL = 数字量\r\n; 注意：WAIT_TICKS 依赖 IRQ0 的 TICK1MS，调用前必须已经开中断\r\nADC_READ_POLL PROC\r\n        PUSH    DX\r\n        PUSH    CX\r\n        MOV     DX, ADC_PORT\r\n        XOR     AL, AL              ; 选 IN0 并启动\r\n        OUT     DX, AL\r\n\r\n        MOV     CX, 2               ; 0809 在 500kHz 下转换约 100us，2ms 足够\r\n        CALL    WAIT_TICKS\r\n\r\n        IN      AL, DX              ; OE 有效，读回 0~255\r\n        POP     CX\r\n        POP     DX\r\n        RET\r\nADC_READ_POLL ENDP\r\n\r\n;=====================================================================\r\n; 九、显示模块\r\n;=====================================================================\r\n; AL=00~99，DI=个位（右位），个位写 [DI]，十位写 [DI+1]\r\nSHOW2   PROC\r\n        PUSH    AX\r\n        PUSH    BX\r\n        PUSH    CX\r\n        PUSH    DX\r\n        PUSH    SI\r\n\r\n        ; AL = 00~99，拆成十位和个位\r\n        XOR     AH, AH\r\n        MOV     BL, 10\r\n        DIV     BL                  ; AL=十位，AH=个位\r\n        MOV     CH, AH              ; CH=个位\r\n        MOV     CL, AL              ; CL=十位\r\n\r\n        ; 十位、个位分别查七段码\r\n        LEA     BX, SEG_TAB\r\n        MOV     AL, CL\r\n        XLAT                        ; AL=十位段码\r\n        MOV     DL, AL\r\n\r\n        MOV     AL, CH\r\n        XLAT                        ; AL=个位段码\r\n        MOV     DH, AL\r\n\r\n        ; [DI]=个位（右/小地址），[DI+1]=十位（左/大地址）\r\n        LEA     SI, DISP_BUF\r\n        ADD     SI, DI\r\n        MOV     [SI], DH\r\n        MOV     [SI+1], DL\r\n\r\n        POP     SI\r\n        POP     DX\r\n        POP     CX\r\n        POP     BX\r\n        POP     AX\r\n        RET\r\nSHOW2   ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; AL=0~9，DI=0~5（0 最右），显示一位\r\nSHOW1   PROC\r\n        PUSH    AX\r\n        PUSH    BX\r\n        PUSH    SI\r\n\r\n        LEA     BX, SEG_TAB\r\n        XLAT\r\n        LEA     SI, DISP_BUF\r\n        ADD     SI, DI\r\n        MOV     [SI], AL\r\n\r\n        POP     SI\r\n        POP     BX\r\n        POP     AX\r\n        RET\r\nSHOW1   ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; AL=00~FF，十六进制显示在最右两位：低 4 位在 [0]，高 4 位在 [1]\r\nSHOW_HEX3 PROC\r\n        PUSH    AX\r\n        PUSH    BX\r\n        PUSH    CX\r\n        PUSH    SI\r\n\r\n        LEA     SI, DISP_BUF\r\n        MOV     AH, AL              ; AH 暂存原值\r\n        MOV     CL, 4\r\n        SHR     AL, CL              ; AL=高 4 位\r\n        AND     AH, 0FH             ; AH=低 4 位\r\n\r\n        LEA     BX, SEG_TAB\r\n        XLAT                        ; 高 4 位查表\r\n        MOV     [SI+1], AL          ; 高位在左\r\n        MOV     AL, AH\r\n        XLAT                        ; 低 4 位查表\r\n        MOV     [SI+0], AL          ; 低位在右\r\n\r\n        ; 其余 4 位熄灭\r\n        XOR     AL, AL\r\n        MOV     [SI+2], AL\r\n        MOV     [SI+3], AL\r\n        MOV     [SI+4], AL\r\n        MOV     [SI+5], AL\r\n\r\n        POP     SI\r\n        POP     CX\r\n        POP     BX\r\n        POP     AX\r\n        RET\r\nSHOW_HEX3 ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; AL=0~255，十进制显示在最右三位：个位[0]、十位[1]、百位[2]\r\nSHOW_DEC3 PROC\r\n        PUSH    AX\r\n        PUSH    BX\r\n        PUSH    CX\r\n        PUSH    DX\r\n        PUSH    SI\r\n\r\n        ; AL=0~255，先除 100 得百位，再除 10 得十位和个位\r\n        MOV     AH, 0\r\n        MOV     BL, 100\r\n        DIV     BL                  ; AL=百位，AH=余数\r\n        MOV     CH, AL              ; CH=百位\r\n        MOV     AL, AH\r\n        XOR     AH, AH\r\n        MOV     BL, 10\r\n        DIV     BL                  ; AL=十位，AH=个位\r\n        MOV     CL, AL              ; CL=十位\r\n        MOV     DH, AH              ; DH=个位\r\n\r\n        LEA     BX, SEG_TAB\r\n        LEA     SI, DISP_BUF\r\n\r\n        ; 百位：为 0 时熄灭（前导 0 不显示）\r\n        MOV     AL, CH\r\n        CMP     AL, 0\r\n        JNE     DEC3_H\r\n        MOV     AL, 0\r\n        JMP     DEC3_HS\r\nDEC3_H:\r\n        XLAT\r\nDEC3_HS:\r\n        MOV     [SI+2], AL\r\n\r\n        ; 十位：百位和十位都为 0 时熄灭\r\n        MOV     AL, CL\r\n        CMP     CH, 0\r\n        JNE     DEC3_T\r\n        CMP     CL, 0\r\n        JNE     DEC3_T\r\n        MOV     AL, 0\r\n        JMP     DEC3_TS\r\nDEC3_T:\r\n        XLAT\r\nDEC3_TS:\r\n        MOV     [SI+1], AL\r\n\r\n        ; 个位必须显示\r\n        MOV     AL, DH\r\n        XLAT\r\n        MOV     [SI+0], AL\r\n\r\n        ; 左边 3 位熄灭\r\n        XOR     AL, AL\r\n        MOV     [SI+3], AL\r\n        MOV     [SI+4], AL\r\n        MOV     [SI+5], AL\r\n\r\n        POP     SI\r\n        POP     DX\r\n        POP     CX\r\n        POP     BX\r\n        POP     AX\r\n        RET\r\nSHOW_DEC3 ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; AL=n（0~255），按 q=n/51、s 四舍五入，显示 U q.s\r\n; 第 5 位“U”，第 1 位 q 并带小数点，第 0 位 s，2~4 位熄灭\r\nSHOW_VOLT PROC\r\n        PUSH    AX\r\n        PUSH    BX\r\n        PUSH    DX\r\n        PUSH    SI\r\n        LEA     SI, DISP_BUF\r\n\r\n        ; S1：q = n / 51，r = n % 51\r\n        MOV     AH, 0\r\n        MOV     BL, 51\r\n        DIV     BL\r\n        MOV     DL, AL              ; DL=q\r\n\r\n        ; S2：m1 = r / 5，m2 = r % 5\r\n        MOV     AL, AH\r\n        MOV     AH, 0\r\n        MOV     BL, 5\r\n        DIV     BL\r\n\r\n        ; S3：m2 >= 3 时小数位进 1\r\n        CMP     AH, 3\r\n        JB      VOLT_NO_ROUND\r\n        INC     AL\r\nVOLT_NO_ROUND:\r\n        ; 若 s=10，向整数位进位\r\n        CMP     AL, 10\r\n        JB      VOLT_NO_CARRY\r\n        SUB     AL, 10\r\n        INC     DL\r\nVOLT_NO_CARRY:\r\n        ; 小数位 s 写最右 [0]，整数位 q 带小数点写 [1]\r\n        LEA     BX, SEG_TAB\r\n        XLAT\r\n        MOV     [SI+0], AL\r\n\r\n        MOV     AL, DL\r\n        XLAT\r\n        OR      AL, 80H             ; DP 位\r\n        MOV     [SI+1], AL\r\n\r\n        ; 中间 3 位熄灭，最左 [5] 显示 U\r\n        XOR     AL, AL\r\n        MOV     [SI+2], AL\r\n        MOV     [SI+3], AL\r\n        MOV     [SI+4], AL\r\n        MOV     AL, 3EH\r\n        MOV     [SI+5], AL\r\n\r\n        POP     SI\r\n        POP     DX\r\n        POP     BX\r\n        POP     AX\r\n        RET\r\nSHOW_VOLT ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; 显示缓冲清 0（段码 0 = 不亮），共 6 位\r\nCLEAR_BUF PROC\r\n        PUSH    AX\r\n        PUSH    CX\r\n        PUSH    SI\r\n        LEA     SI, DISP_BUF\r\n        MOV     CX, 6\r\n        XOR     AL, AL\r\nCB1:\r\n        MOV     [SI], AL\r\n        INC     SI\r\n        LOOP    CB1\r\n        POP     SI\r\n        POP     CX\r\n        POP     AX\r\n        RET\r\nCLEAR_BUF ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; 动态扫描：PA 段码，PC 位选；PC0 最右，扫描 0~5\r\nDISP_SCAN PROC\r\n        PUSH    AX\r\n        PUSH    BX\r\n        PUSH    CX\r\n        PUSH    DX\r\n        PUSH    SI\r\n\r\n        ; 1) 先关位选，消隐，避免换位时出现鬼影\r\n        MOV     DX, P8255_PC\r\n        XOR     AL, AL\r\n        OUT     DX, AL\r\n\r\n        ; 2) 取当前位的段码，送 PA\r\n        MOV     BL, DISP_IDX\r\n        XOR     BH, BH\r\n        LEA     SI, DISP_BUF\r\n        MOV     AL, [SI+BX]\r\n        XOR     AL, SEG_INVERT\r\n        MOV     DX, P8255_PA\r\n        OUT     DX, AL\r\n\r\n        ; 3) 1 << 当前位，送 PC 位选；PC0 最右\r\n        MOV     AL, 1\r\n        MOV     CL, BL\r\n        SHL     AL, CL\r\n        XOR     AL, DIG_INVERT\r\n        MOV     DX, P8255_PC\r\n        OUT     DX, AL\r\n\r\n        ; 4) 保持一小段时间，再换下一位\r\n        CALL    DLY_SCAN\r\n\r\n        ; 5) 位号 0~5 循环\r\n        MOV     BL, DISP_IDX\r\n        INC     BL\r\n        CMP     BL, 6\r\n        JB      DISP_IDX_OK\r\n        XOR     BL, BL\r\nDISP_IDX_OK:\r\n        MOV     DISP_IDX, BL\r\n\r\n        POP     SI\r\n        POP     DX\r\n        POP     CX\r\n        POP     BX\r\n        POP     AX\r\n        RET\r\nDISP_SCAN ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; 扫描延时：软件循环，DISP_DELAY 越大越亮\r\nDLY_SCAN PROC\r\n        PUSH    CX\r\n        MOV     CX, DISP_DELAY\r\nDL1:\r\n        LOOP    DL1\r\n        POP     CX\r\n        RET\r\nDLY_SCAN ENDP\r\n\r\n;=====================================================================\r\n; 十、LED、延时、点阵\r\n;=====================================================================\r\nLED_NEXT PROC\r\n        PUSH    AX\r\n        PUSH    BX\r\n        PUSH    DX\r\n\r\n        ; LED_N：已亮个数 0~8；到 8 后回 0\r\n        MOV     AL, LED_N\r\n        CMP     AL, 8\r\n        JAE     LED_NEXT_OFF\r\n        INC     AL\r\n        JMP     LED_NEXT_SHOW\r\nLED_NEXT_OFF:\r\n        XOR     AL, AL\r\nLED_NEXT_SHOW:\r\n        MOV     LED_N, AL\r\n        LEA     BX, LED_TAB\r\n        XLAT                        ; 取 n 个亮的图案\r\n        XOR     AL, LED_INVERT      ; 低电平点亮时取反\r\n        MOV     DX, P8255_PB\r\n        OUT     DX, AL\r\n\r\n        POP     DX\r\n        POP     BX\r\n        POP     AX\r\n        RET\r\nLED_NEXT ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; 等 TICK1MS 变化一次（1ms），要求 IRQ0 已经开\r\n; 原理：先读旧值，再循环比较；中断里 INC TICK1MS 后跳出\r\nWAIT_1MS PROC\r\n        PUSH    AX\r\n        MOV     AX, TICK1MS\r\nWAIT_1MS_LOOP:\r\n        CMP     AX, TICK1MS\r\n        JE      WAIT_1MS_LOOP\r\n        POP     AX\r\n        RET\r\nWAIT_1MS ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; 等 CX 个 1ms；CX 由调用者给\r\nWAIT_TICKS PROC\r\n        PUSH    AX\r\n        PUSH    CX\r\nWAIT_TICKS_LOOP:\r\n        CALL    WAIT_1MS\r\n        LOOP    WAIT_TICKS_LOOP\r\n        POP     CX\r\n        POP     AX\r\n        RET\r\nWAIT_TICKS ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; 8×8 点阵显示“接口技术”，每列 1ms，每字 1.8s\r\n;   CX=225 帧，每帧 8 列，每列 1ms -> 225*8ms = 1.8s\r\n;   PA 送行数据，PB 送列选通（01H 左移到 80H）\r\n; 用法：把 MAIN 里的 JMP MAIN 改成 JMP MATRIX_DEMO\r\nMATRIX_DEMO PROC\r\n        STI                         ; WAIT_1MS 需要 IRQ0\r\n        LEA     SI, FONT\r\n        MOV     BP, CHARS\r\n\r\nMAT_NEXT_CHAR:\r\n        MOV     CX, FRAMES_PER_CHAR\r\n\r\nMAT_FRAME:\r\n        MOV     BX, 8               ; 8 列\r\n        MOV     AH, 01H             ; 列选通初值：PB0\r\n\r\nMAT_COL:\r\n        ; 行数据 -> PA\r\n        MOV     AL, [SI]\r\n        XOR     AL, ROW_INVERT\r\n        MOV     DX, P8255_PA\r\n        OUT     DX, AL\r\n\r\n        ; 列选通 -> PB\r\n        MOV     AL, AH\r\n        XOR     AL, COL_INVERT\r\n        MOV     DX, P8255_PB\r\n        OUT     DX, AL\r\n\r\n        CALL    WAIT_1MS            ; 该列保持 1ms\r\n        SHL     AH, 1               ; 下一列\r\n        INC     SI\r\n        DEC     BX\r\n        JNZ     MAT_COL\r\n\r\n        SUB     SI, 8               ; 回到本字第一列\r\n        LOOP    MAT_FRAME\r\n\r\n        ADD     SI, 8\r\n        DEC     BP\r\n        JNZ     MAT_NEXT_CHAR\r\n\r\n        LEA     SI, FONT\r\n        MOV     BP, CHARS\r\n        JMP     MAT_NEXT_CHAR\r\nMATRIX_DEMO ENDP\r\n\r\n;=====================================================================\r\n; 考试改动索引：\r\n;   1. IRQ_MASK：0FEH 只定时；0FCH 定时+ADC；0FAH 定时+按键；\r\n;      0F8H 定时+ADC+按键\r\n;   2. T_A/T_B/T_C/T_D/T_ADC：周期，单位 ms\r\n;   3. ISR0 里的 CMP CNT_x,上限+1；MOV DI,n 显示位置\r\n;   4. ISR1 里 CALL SHOW_VOLT 可换 SHOW_HEX3 / SHOW_DEC3\r\n;   5. 要跑点阵：JMP MAIN 改 JMP MATRIX_DEMO\r\n;   6. DAC 表 DAC_TAB、LED 表 LED_TAB 按题目改\r\n;=====================================================================\r\n\r\n        END     START\r\n\r\n"},{"id":"8253pulse","name":"实验三-1：8253 计 10 个正脉冲点亮 LED","note":"按“单脉冲 AN1”10 次，OUT0 变高，L1 点亮。","wiring":{"clk0":"AN1","out0Led":true},"source":"﻿;=====================================================================\r\n; 实验三 任务1：8253 接收 10 个正脉冲后点亮 1 个红色 LED\r\n;---------------------------------------------------------------------\r\n; 接线（SHYL-WJ86 实验箱）：\r\n;   1. 地址译码 CS0（200H~20FH）  -> 8253/8254 的 /CS\r\n;   2. 8253 的 D0~D7、/RD、/WR、A0、A1 走板内系统总线，无需再接\r\n;   3. 正脉冲输出（单次正脉冲按钮） -> CLK0\r\n;   4. GATE0 -> +5V（也可以接 K1，运行前把 K1 置高电平）\r\n;   5. OUT0 -> L1（红色 LED 指示，高电平点亮）\r\n;---------------------------------------------------------------------\r\n; 工作方式：\r\n;   计数器0 方式0（计满中断），二进制，先写低字节后写高字节。\r\n;   初值写入 10；每来一个正脉冲（下降沿计数），计数器减1；\r\n;   计满 10 个脉冲后 OUT0 由低变高并保持，LED 点亮。\r\n;   控制字 = 0011 0000B = 30H。\r\n;\r\n; 注意：若 L1 是低电平点亮，计满后 OUT0 变高反而会使 LED 熄灭；\r\n;       在 OUT0 与 L1 之间加一级 74LS04 反相器即可。\r\n;=====================================================================\r\n\r\n        .8086\r\n        .MODEL SMALL\r\n        .STACK 100H\r\n\r\n        .CODE\r\nSTART   PROC\r\n        ;---- 8253 计数器0：方式0，先低后高，二进制 ----\r\n        MOV     DX, 0203H          ; 8253 控制寄存器\r\n        MOV     AL, 30H            ; 计数器0，方式0，读写16位，二进制\r\n        OUT     DX, AL\r\n\r\n        ;---- 写入计数初值 10 ----\r\n        MOV     DX, 0200H          ; 计数器0\r\n        MOV     AX, 10\r\n        OUT     DX, AL             ; 先写低字节\r\n        MOV     AL, AH\r\n        OUT     DX, AL             ; 再写高字节\r\n\r\n        ;---- 等待 10 个正脉冲，OUT0 变高后 LED 保持点亮 ----\r\nHERE:   JMP     HERE\r\n\r\nSTART   ENDP\r\n        END     START\r\n\r\n"},{"id":"8253square","name":"实验三-2：8253 产生 2 秒方波驱动 LED","note":"OUT0→CLK1 级联，OUT1→L1；灯亮 1 秒、灭 1 秒。","wiring":{"out0Clk1":true,"out1Led":true},"source":"﻿;=====================================================================\r\n; 实验三 任务2：8253 产生周期 2 秒的方波，驱动一个 LED\r\n;---------------------------------------------------------------------\r\n; 接线（SHYL-WJ86 实验箱）：\r\n;   1. 地址译码 CS0（200H~20FH）  -> 8253/8254 的 /CS\r\n;   2. 8253 的 D0~D7、/RD、/WR、A0、A1 走板内系统总线，无需再接\r\n;   3. 1MHz 固定脉冲输出 -> CLK0\r\n;   4. OUT0 -> CLK1\r\n;   5. GATE0、GATE1 -> +5V（或接 K1 并置高）\r\n;   6. OUT1 -> L1（LED，高电平点亮）\r\n;---------------------------------------------------------------------\r\n; 计算：\r\n;   1MHz / 1000 = 1kHz              （计数器0，方式3，初值1000）\r\n;   1kHz / 2000 = 0.5Hz，周期2s     （计数器1，方式3，初值2000）\r\n;   方式3为方波，因此高电平1s、低电平1s。\r\n;   控制字：计数器0 = 0011 0110B = 36H\r\n;           计数器1 = 0111 0110B = 76H\r\n;\r\n; 注意：L1 必须接 OUT1，不能接 OUT0！OUT0 是 1kHz 方波，\r\n;       接灯看起来会一直亮；只有 OUT1 才是 0.5Hz、1秒亮1秒灭。\r\n;=====================================================================\r\n\r\n        .8086\r\n        .MODEL SMALL\r\n        .STACK 100H\r\n\r\n        .CODE\r\nSTART   PROC\r\n        ;---- 计数器0：方式3，初值1000，输出1kHz ----\r\n        MOV     DX, 0203H\r\n        MOV     AL, 36H            ; 计数器0，方式3，先低后高，二进制\r\n        OUT     DX, AL\r\n\r\n        MOV     DX, 0200H\r\n        MOV     AX, 1000\r\n        OUT     DX, AL\r\n        MOV     AL, AH\r\n        OUT     DX, AL\r\n\r\n        ;---- 计数器1：方式3，初值2000，输出0.5Hz方波 ----\r\n        MOV     DX, 0203H\r\n        MOV     AL, 76H            ; 计数器1，方式3，先低后高，二进制\r\n        OUT     DX, AL\r\n\r\n        MOV     DX, 0201H\r\n        MOV     AX, 2000\r\n        OUT     DX, AL\r\n        MOV     AL, AH\r\n        OUT     DX, AL\r\n\r\n        ;---- 方波由 OUT1 一直输出 ----\r\nHERE:   JMP     HERE\r\n\r\nSTART   ENDP\r\n        END     START\r\n\r\n"},{"id":"8259key","name":"实验五-1：8259 按键中断 0~9 循环显示","note":"每按一次“单脉冲 AN2”，数码管加 1，9 后回 0。","wiring":{"digitReverse":true},"source":"﻿;=====================================================================\n; 实验五 任务1：手动脉冲中断，数码管 0~9 循环显示\n;---------------------------------------------------------------------\n; 接线（SHYL-WJ86 实验箱）：\n;   1. 地址译码 CS3（230H~23FH） -> 8259 的 M8259CS\n;   2. CPU 的 INTR -> 8259 的 INT；CPU 的 INTA -> 8259 的 INTA\n;   3. 单脉冲 AN2 -> 8259 的 IRQ2\n;   4. 8255 的 /CS -> CS1（210H~213H）\n;   5. 8255 PA0~PA7 -> 数码管段码总线 LEDB\n;      8255 PC0~PC7 -> 数码管位选总线 BIT\n;   6. 8259 的 D0~D7、/RD、/WR、A0 走板内系统总线，不用再接\n;---------------------------------------------------------------------\n; 原理：\n;   8259 初始化成“单片、边沿触发、8086 模式”，ICW2=08H，\n;   因此 IRQ2 对应的中断类型号是 08H+2 = 0AH。\n;   主程序把 0AH 的中断向量指向 IRQ2_ISR，开中断后循环扫描数码管。\n;   每按一次 AN2，IRQ2 得到一个上升沿，8259 向 CPU 发 INT；\n;   CPU 响应后进入 IRQ2_ISR：先发 EOI，再把显示值加 1（0~9 循环）。\n;---------------------------------------------------------------------\n; 现象：上电后数码管无显示；第一次按 AN2 显示 0，以后每按一次加 1，\n;       显示 9 后再按一次回到 0，如此循环。\n;=====================================================================\n\n        .8086\n        .MODEL SMALL\n        .STACK 100H\n\n;---- 端口地址（以实验箱面板丝印为准）----\nP8255_PA        EQU     0210H\nP8255_PB        EQU     0211H\nP8255_PC        EQU     0212H\nP8255_CTRL      EQU     0213H\nP8259_0         EQU     0230H           ; 8259 偶地址：ICW1/OCW2/OCW3\nP8259_1         EQU     0231H           ; 8259 奇地址：ICW2~ICW4/OCW1\n\n;---- 中断设置：本任务用 IRQ2 ----\nIRQ_NO          EQU     2\nIRQ_VECT        EQU     08H + IRQ_NO  ; = 0AH\nIRQ_MASK        EQU     0FBH           ; 只开 IRQ2（0=允许）\n\n;---- 数码管接法 ----\nDISP_SEG_PORT   EQU     P8255_PA       ; 段码总线 LEDB 接 PA\nDISP_DIG_PORT   EQU     P8255_PC       ; 位选总线 BIT 接 PC\nSEG_INVERT      EQU     0              ; 共阳数码管（段低有效）改为 0FFH\nDIG_INVERT      EQU     0              ; 位选低有效改为 0FFH\nDISP_DELAY      EQU     120            ; 扫描延时，越大越亮（0~255）\n\n        .DATA\n;---- 共阴七段码 0~9、A~F ----\nSEG_TAB DB      3FH,06H,5BH,4FH,66H,6DH,7DH,07H,7FH,6FH\n        DB      77H,7CH,39H,5EH,79H,71H\nDISP_BUF DB     0,0,0,0,0,0,0,0        ; 8 位显示缓冲，0 号最左、7 号最右\nDISP_IDX DB     0                      ; 当前扫描位\nCOUNT   DB     0FFH                    ; FFH=还没按过（无显示），0~9=显示值\n\n        .CODE\nSTART   PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n\n        CALL    INIT_8255\n        CALL    CLEAR_BUF\n        CALL    INIT_8259\n        CALL    INSTALL_VECT\n        CALL    ENABLE_IRQ\n        STI\n\nMAIN:\n        CALL    DISP_SCAN             ; 主循环只做动态扫描\n        JMP     MAIN\nSTART   ENDP\n\n;---------------------------------------------------------------------\n; INIT_8255：A、B、C 口全部方式0输出（PA 段码、PC 位选）\n;---------------------------------------------------------------------\nINIT_8255 PROC\n        MOV     DX, P8255_CTRL\n        MOV     AL, 80H               ; 1000 0000B：三口全输出\n        OUT     DX, AL\n\n        MOV     DX, DISP_SEG_PORT\n        XOR     AL, AL\n        OUT     DX, AL\n        MOV     DX, DISP_DIG_PORT\n        OUT     DX, AL\n        MOV     DX, P8255_PB\n        OUT     DX, AL\n        RET\nINIT_8255 ENDP\n\n;---------------------------------------------------------------------\n; INIT_8259：ICW1=13H（边沿、单片、需要ICW4）\n;            ICW2=08H（IRQ0 对应类型号 08H）\n;            ICW4=01H（8086 模式、普通 EOI）\n;            OCW1=FFH（先全部屏蔽，初始化完再开）\n;---------------------------------------------------------------------\nINIT_8259 PROC\n        MOV     DX, P8259_0\n        MOV     AL, 13H\n        OUT     DX, AL\n\n        MOV     DX, P8259_1\n        MOV     AL, 08H\n        OUT     DX, AL\n        MOV     AL, 01H\n        OUT     DX, AL\n\n        MOV     AL, 0FFH\n        OUT     DX, AL\n        RET\nINIT_8259 ENDP\n\n;---------------------------------------------------------------------\n; ENABLE_IRQ：OCW1 写允许掩码，只放行本任务用的中断\n;---------------------------------------------------------------------\nENABLE_IRQ PROC\n        MOV     DX, P8259_1\n        MOV     AL, IRQ_MASK\n        OUT     DX, AL\n        RET\nENABLE_IRQ ENDP\n\n;---------------------------------------------------------------------\n; INSTALL_VECT：把 IRQ_VECT 号中断向量指向 IRQ2_ISR\n;---------------------------------------------------------------------\nINSTALL_VECT PROC\n        PUSH    AX\n        PUSH    DI\n        PUSH    ES\n        MOV     AX, 0\n        MOV     ES, AX\n        MOV     DI, IRQ_VECT*4\n        MOV     AX, OFFSET IRQ2_ISR\n        MOV     ES:[DI], AX\n        MOV     AX, CS\n        MOV     ES:[DI+2], AX\n        POP     ES\n        POP     DI\n        POP     AX\n        RET\nINSTALL_VECT ENDP\n\n;---------------------------------------------------------------------\n; IRQ2_ISR：按键中断服务程序\n;   1. 发 EOI\n;   2. 第一次按：显示 0；以后每次加 1，超过 9 回 0\n;---------------------------------------------------------------------\nIRQ2_ISR PROC  FAR\n        PUSH    AX\n        PUSH    BX\n        PUSH    DX\n        PUSH    DS\n        MOV     AX, @DATA\n        MOV     DS, AX\n\n        MOV     DX, P8259_0           ; OCW2：普通 EOI\n        MOV     AL, 20H\n        OUT     DX, AL\n\n        MOV     AL, COUNT\n        CMP     AL, 0FFH\n        JNE     ISR_ADD\n        XOR     AL, AL                ; 第一次按，从 0 开始\n        JMP     ISR_SHOW\n\nISR_ADD:\n        INC     AL\n        CMP     AL, 10\n        JB      ISR_SHOW\n        XOR     AL, AL                ; 9 之后回到 0\n\nISR_SHOW:\n        MOV     COUNT, AL\n        LEA     BX, SEG_TAB\n        XLAT                          ; AL = 七段码\n        LEA     BX, DISP_BUF\n        MOV     [BX+7], AL            ; 显示在最右一位\n\n        POP     DS\n        POP     DX\n        POP     BX\n        POP     AX\n        IRET\nIRQ2_ISR ENDP\n\n;---------------------------------------------------------------------\n; CLEAR_BUF：显示缓冲清 0（段码 0 = 不亮）\n;---------------------------------------------------------------------\nCLEAR_BUF PROC\n        PUSH    AX\n        PUSH    CX\n        PUSH    SI\n        LEA     SI, DISP_BUF\n        MOV     CX, 8\n        XOR     AL, AL\nCB1:\n        MOV     [SI], AL\n        INC     SI\n        LOOP    CB1\n        POP     SI\n        POP     CX\n        POP     AX\n        RET\nCLEAR_BUF ENDP\n\n;---------------------------------------------------------------------\n; DISP_SCAN：动态扫描一位\n;   先关位选消隐 -> 送段码 -> 送位选 -> 延时\n;---------------------------------------------------------------------\nDISP_SCAN PROC\n        PUSH    AX\n        PUSH    BX\n        PUSH    CX\n        PUSH    SI\n\n        MOV     DX, DISP_DIG_PORT\n        XOR     AL, AL\n        OUT     DX, AL                ; 全部位选关断，消隐\n\n        MOV     BL, DISP_IDX\n        XOR     BH, BH\n        LEA     SI, DISP_BUF\n        MOV     AL, [SI+BX]\n        XOR     AL, SEG_INVERT\n        MOV     DX, DISP_SEG_PORT\n        OUT     DX, AL                ; 送段码\n\n        MOV     AL, 1\n        MOV     CL, BL\n        SHL     AL, CL                ; 1 << 当前位\n        XOR     AL, DIG_INVERT\n        MOV     DX, DISP_DIG_PORT\n        OUT     DX, AL                ; 送位选\n\n        CALL    DLY_SCAN\n\n        MOV     BL, DISP_IDX\n        INC     BL\n        AND     BL, 7\n        MOV     DISP_IDX, BL\n\n        POP     SI\n        POP     CX\n        POP     BX\n        POP     AX\n        RET\nDISP_SCAN ENDP\n\n;---------------------------------------------------------------------\n; DLY_SCAN：扫描延时（软件循环，改 DISP_DELAY 调亮度）\n;---------------------------------------------------------------------\nDLY_SCAN PROC\n        PUSH    CX\n        MOV     CX, DISP_DELAY\nDL1:\n        LOOP    DL1\n        POP     CX\n        RET\nDLY_SCAN ENDP\n\n;=====================================================================\n; 调整提示：\n;   1. 数码管全灭或全亮：改 SEG_INVERT（共阳改 0FFH）；\n;      位选不对：改 DIG_INVERT 或把 PC0~PC7 接线顺序反过来。\n;   2. 显示偏左：把 IRQ2_ISR 里的 [BX+7] 改成 [BX+0] 或其它位。\n;   3. 按 AN2 没反应：先查 INT/INTA 两根线、CS3 线、8259 的 A0，\n;      再查 IRQ_MASK 是否为 0FBH、中断服务程序里是否发了 EOI。\n;   4. 若数码管模块是“BCD 译码输入”，把 SEG_TAB 改成\n;      00H,01H,02H,...,09H 即可（段码由模块内部译码）。\n;=====================================================================\n\n        END     START\n\r\n"},{"id":"dac","name":"实验四-1：0832 输出 1V/2V/3V/4V/4.5V","note":"OUT0→PC7 提供 1ms 节拍，每个电压保持 2 秒。","wiring":{"out0Pc7":true},"source":"﻿;=====================================================================\n; 实验四 任务1：用 DAC0832 分别产生 1V、2V、3V、4V、4.5V 电压\n;---------------------------------------------------------------------\n; 接线（SHYL-WJ86 实验箱）：\n;   1. 地址译码 CS0（200H~20FH） -> 8253/8254 的 /CS\n;   2. 1MHz 固定脉冲 -> CLK0；GATE0 -> +5V\n;   3. 8253 OUT0 -> 8255 PC7（1kHz 节拍，用于 2 秒定时）\n;   4. 8255 的 /CS 接 210H~213H 译码输出（板内已固定则不用再接）\n;   5. 0832CS -> 实验箱面板上标有 0832CS 的译码输出\n;      本程序默认 DAC_PORT = 250H，若面板标注不同，改下面的 EQU\n;   6. 0832 的 DI0~DI7、/WR1、/WR2、/XFER 走板内总线，无需另接\n;   7. DAOUT（J1 输出）接万用表/示波器观察电压\n;   8. 用 W1 把 Uref 调到 +5V；更简单的校准：运行 TEST_DA.ASM，\n;      输出 2.5V 时调 W1 使 DAOUT=2.5V\n;---------------------------------------------------------------------\n; 电压与数字量的关系（实验指导书给出）：\n;       DAOUT = 2 * Uref * N / 256 - 5      (Uref = +5V)\n;   即   N = (U + 5) * 256 / 10 = (U + 5) * 25.6\n;   U=1.0V -> N=154    U=2.0V -> N=179    U=3.0V -> N=205\n;   U=4.0V -> N=230    U=4.5V -> N=243\n;---------------------------------------------------------------------\n; 现象：DAOUT 依次输出 1.0、2.0、3.0、4.0、4.5V，每个电压保持 2 秒，\n;       然后循环。用万用表可以直接读到这 5 个电压。\n;=====================================================================\n\n        .8086\n        .MODEL SMALL\n        .STACK 100H\n\n;---- 端口地址 ----\nP8253_C0        EQU     0200H\nP8253_CTRL      EQU     0203H\nP8255_PC        EQU     0212H\nP8255_CTRL      EQU     0213H\nDAC_PORT        EQU     0250H           ; <== 按实验箱面板 0832CS 标注修改\n\n;---- 1=按指导书的双极性公式；0=若实测为 0~5V 单极性，则用 0 ----\nDAC_BIPOLAR     EQU     1\n\n        .DATA\n;---- 双极性公式 N=(U+5)*25.6 对应的数字量 ----\nTAB_BIP DB      154,179,205,230,243\n;---- 单极性公式 N=U*51.2 对应的数字量（备用） ----\nTAB_UNI DB      51,102,154,205,230\nTAB_PTR DW      0\n\n        .CODE\nSTART   PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n\n        CALL    INIT_8255\n        CALL    INIT_8253\n\n        ;---- 根据 DAC_BIPOLAR 选择数字量表 ----\n        LEA     AX, TAB_BIP\n        MOV     BL, DAC_BIPOLAR\n        OR      BL, BL\n        JNZ     TAB_OK\n        LEA     AX, TAB_UNI\nTAB_OK:\n        MOV     TAB_PTR, AX\n\nMAIN:\n        MOV     SI, TAB_PTR\n        MOV     BP, 5\nNEXT_V:\n        MOV     AL, [SI]            ; 取本电压对应的数字量\n        MOV     DX, DAC_PORT\n        OUT     DX, AL              ; 写入 0832，DAOUT 变为目标电压\n        CALL    DELAY_2S            ; 保持 2 秒\n        INC     SI\n        DEC     BP\n        JNZ     NEXT_V\n        JMP     MAIN                ; 5 个电压输出完，从头循环\nSTART   ENDP\n\n;---------------------------------------------------------------------\n; INIT_8255：A、B 口输出，C 口输入（PC7 读 8253 OUT0）\n;---------------------------------------------------------------------\nINIT_8255 PROC\n        MOV     DX, P8255_CTRL\n        MOV     AL, 89H             ; 1000 1001B\n        OUT     DX, AL\n        RET\nINIT_8255 ENDP\n\n;---------------------------------------------------------------------\n; INIT_8253：计数器0，方式3，1MHz/1000 = 1kHz 方波\n;---------------------------------------------------------------------\nINIT_8253 PROC\n        MOV     DX, P8253_CTRL\n        MOV     AL, 36H             ; 计数器0，方式3，先低后高，二进制\n        OUT     DX, AL\n        MOV     DX, P8253_C0\n        MOV     AX, 1000\n        OUT     DX, AL              ; 低字节\n        MOV     AL, AH\n        OUT     DX, AL              ; 高字节\n        RET\nINIT_8253 ENDP\n\n;---------------------------------------------------------------------\n; WAIT_TICK：等待 PC7 上 1kHz 方波的一个上升沿（1ms）\n; 先等低电平，再等上升沿，保证每次调用跨过完整 1ms。\n;---------------------------------------------------------------------\nWAIT_TICK PROC\n        PUSH    DX\n        PUSH    AX\n        MOV     DX, P8255_PC\nWT_LOW:\n        IN      AL, DX\n        TEST    AL, 80H\n        JNZ     WT_LOW\nWT_HIGH:\n        IN      AL, DX\n        TEST    AL, 80H\n        JZ      WT_HIGH\n        POP     AX\n        POP     DX\n        RET\nWAIT_TICK ENDP\n\n;---------------------------------------------------------------------\n; DELAY_2S：延时 2000 个 1ms 节拍 = 2 秒\n;---------------------------------------------------------------------\nDELAY_2S PROC\n        PUSH    CX\n        MOV     CX, 2000\nD2S:\n        CALL    WAIT_TICK\n        LOOP    D2S\n        POP     CX\n        RET\nDELAY_2S ENDP\n\n        END     START\n\r\n"},{"id":"adchex","name":"实验四-3：0809 采样，十六进制显示","note":"拖动 IN0 电位器，最右两位显示 00~FF。","wiring":{"out0Pc7":true,"digitReverse":true,"digitPort":"PB"},"source":"﻿;=====================================================================\n; 实验四 任务3：每 100ms 采样 0~5V 直流电压，\n;                把 A/D 得到的数字量以十六进制显示在 8 位数码管上\n;---------------------------------------------------------------------\n; 接线（SHYL-WJ86 实验箱）：\n;   1. 8253 /CS -> CS0（200H~20FH）；1MHz -> CLK0；GATE0 -> +5V\n;   2. 8253 OUT0 -> 8255 PC7（1kHz 节拍：1ms 一个上升沿）\n;   3. 8255 /CS -> 210H~213H 译码输出\n;   4. 0809CS -> 实验箱面板 0809CS 译码输出（默认 ADC_PORT=260H）\n;   5. 0809CLK -> 500kHz 固定脉冲（必须接，否则 ADC 不转换）\n;   6. ADC0809 的 IN0 -> 实验箱直流电源 0~5V（或电位器中心抽头）\n;   7. 数码管显示（动态扫描）：\n;        8255 PA0~PA7 -> 段 a,b,c,d,e,f,g,dp\n;        8255 PB0~PB7 -> 位选 DIG1~DIG8（PB0 最左，PB7 最右）\n;      本程序按“共阴数码管、段高电平点亮、位选高有效”编写；\n;      若为共阳/低有效，把 SEG_INVERT、DIGIT_INVERT 改为 0FFH。\n;---------------------------------------------------------------------\n; 原理：\n;   8253 计数器0 方式3，1MHz/1000 = 1kHz，OUT0 接 PC7；\n;   程序查询 PC7 的上升沿，得到 1ms 节拍；\n;   每个节拍刷新一位数码管，8ms 扫完一帧（125Hz，不闪烁）；\n;   每 100 个节拍（100ms）启动一次 A/D：\n;       写 ADC 端口（D0~D2=0 选 IN0）-> START/ALE 有效，开始转换；\n;       延时 2ms（0809 在 500kHz 下转换约 100us，2ms 足够）；\n;       读 ADC 端口 -> OE 有效，取回 8 位数字量 n；\n;   n 的高 4 位、低 4 位分别查表换成七段码，显示在最右两位。\n;---------------------------------------------------------------------\n; 现象：调节直流电压，最右两位十六进制数在 00~FF 之间变化。\n;=====================================================================\n\n        .8086\n        .MODEL SMALL\n        .STACK 100H\n\n;---- 端口地址 ----\nP8253_C0        EQU     0200H\nP8253_CTRL      EQU     0203H\nP8255_PA        EQU     0210H\nP8255_PB        EQU     0211H\nP8255_PC        EQU     0212H\nP8255_CTRL      EQU     0213H\nADC_PORT        EQU     0260H           ; <== 按实验箱面板 0809CS 标注修改\n\n;---- 数码管极性 ----\nSEG_INVERT      EQU     0               ; 共阳数码管改为 0FFH\nDIGIT_INVERT    EQU     0               ; 位选低有效改为 0FFH\n\n        .DATA\n;---- 共阴七段码 0~9、A~F ----\nSEG_TAB DB      3FH,06H,5BH,4FH,66H,6DH,7DH,07H,7FH,6FH\n        DB      77H,7CH,39H,5EH,79H,71H\nDISP_BUF DB     0,0,0,0,0,0,0,0         ; 8 位显示缓冲（存七段码）\nDISP_IDX DW     0                       ; 当前扫描位 0~7\n\n        .CODE\nSTART   PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n\n        CALL    INIT_8255\n        CALL    INIT_8253\n        CALL    CLEAR_BUF\n\nMAIN:\n        CALL    ADC_READ            ; AL = 数字量 n\n        CALL    SHOW_HEX            ; 更新显示缓冲\n        MOV     CX, 98              ; A/D 已用 2ms，再等 98ms\nHOLD:\n        CALL    WAIT_TICK\n        CALL    DISP_NEXT\n        LOOP    HOLD\n        JMP     MAIN                ; 采样周期约 100ms\nSTART   ENDP\n\n;---------------------------------------------------------------------\n; INIT_8255：A、B 口输出（数码管），C 口输入（PC7 读节拍）\n;---------------------------------------------------------------------\nINIT_8255 PROC\n        MOV     DX, P8255_CTRL\n        MOV     AL, 89H             ; 1000 1001B：A/B 输出，C 输入\n        OUT     DX, AL\n        MOV     DX, P8255_PA\n        XOR     AL, AL\n        OUT     DX, AL\n        MOV     DX, P8255_PB\n        OUT     DX, AL\n        RET\nINIT_8255 ENDP\n\n;---------------------------------------------------------------------\n; INIT_8253：计数器0，方式3，初值 1000 -> 1kHz\n;---------------------------------------------------------------------\nINIT_8253 PROC\n        MOV     DX, P8253_CTRL\n        MOV     AL, 36H\n        OUT     DX, AL\n        MOV     DX, P8253_C0\n        MOV     AX, 1000\n        OUT     DX, AL\n        MOV     AL, AH\n        OUT     DX, AL\n        RET\nINIT_8253 ENDP\n\n;---------------------------------------------------------------------\n; CLEAR_BUF：显示缓冲全部清 0（0 = 熄灭）\n;---------------------------------------------------------------------\nCLEAR_BUF PROC\n        PUSH    AX\n        PUSH    CX\n        PUSH    DI\n        LEA     DI, DISP_BUF\n        MOV     CX, 8\n        XOR     AL, AL\nCB1:\n        MOV     [DI], AL\n        INC     DI\n        LOOP    CB1\n        POP     DI\n        POP     CX\n        POP     AX\n        RET\nCLEAR_BUF ENDP\n\n;---------------------------------------------------------------------\n; ADC_READ：启动 A/D，等 2ms，读回结果\n; 返回：AL = 数字量 0~255\n;---------------------------------------------------------------------\nADC_READ PROC\n        PUSH    DX\n        PUSH    CX\n        MOV     DX, ADC_PORT\n        XOR     AL, AL              ; 通道 0；同时启动转换\n        OUT     DX, AL\n        MOV     CX, 2               ; 等 2 个 1ms 节拍，期间保持显示\nAR_WAIT:\n        CALL    WAIT_TICK\n        CALL    DISP_NEXT\n        LOOP    AR_WAIT\n        IN      AL, DX              ; 读结果（OE 有效）\n        POP     CX\n        POP     DX\n        RET\nADC_READ ENDP\n\n;---------------------------------------------------------------------\n; SHOW_HEX：把 AL 中的 n 拆成高/低 4 位，查表后放显示缓冲最右两位\n;---------------------------------------------------------------------\nSHOW_HEX PROC\n        PUSH    AX\n        PUSH    BX\n        PUSH    SI\n        LEA     SI, DISP_BUF\n\n        MOV     AH, AL\n        SHR     AL, 1\n        SHR     AL, 1\n        SHR     AL, 1\n        SHR     AL, 1               ; AL = 高 4 位\n        AND     AH, 0FH             ; AH = 低 4 位\n        LEA     BX, SEG_TAB\n        XLAT                        ; 高 4 位段码\n        MOV     [SI+6], AL\n        MOV     AL, AH\n        XLAT                        ; 低 4 位段码\n        MOV     [SI+7], AL\n\n        XOR     AL, AL              ; 左边 6 位熄灭\n        MOV     [SI+0], AL\n        MOV     [SI+1], AL\n        MOV     [SI+2], AL\n        MOV     [SI+3], AL\n        MOV     [SI+4], AL\n        MOV     [SI+5], AL\n\n        POP     SI\n        POP     BX\n        POP     AX\n        RET\nSHOW_HEX ENDP\n\n;---------------------------------------------------------------------\n; WAIT_TICK：等 PC7 上一个 1ms 节拍（低 -> 高）\n;---------------------------------------------------------------------\nWAIT_TICK PROC\n        PUSH    DX\n        PUSH    AX\n        MOV     DX, P8255_PC\nWT_LOW:\n        IN      AL, DX\n        TEST    AL, 80H\n        JNZ     WT_LOW\nWT_HIGH:\n        IN      AL, DX\n        TEST    AL, 80H\n        JZ      WT_HIGH\n        POP     AX\n        POP     DX\n        RET\nWAIT_TICK ENDP\n\n;---------------------------------------------------------------------\n; DISP_NEXT：动态扫描下一位\n; 先消隐 -> 送位选 -> 送段码，避免换位时出现“鬼影”\n;---------------------------------------------------------------------\nDISP_NEXT PROC\n        PUSH    AX\n        PUSH    BX\n        PUSH    CX\n        PUSH    DX\n        PUSH    SI\n\n        LEA     SI, DISP_BUF\n        MOV     BX, DISP_IDX\n\n        MOV     DX, P8255_PA\n        XOR     AL, AL\n        OUT     DX, AL              ; 段码全 0，消隐\n\n        MOV     AL, 1\n        MOV     CX, BX\n        SHL     AL, CL              ; 1 << 当前位\n        XOR     AL, DIGIT_INVERT\n        MOV     DX, P8255_PB\n        OUT     DX, AL              ; 送位选\n\n        MOV     AL, [SI+BX]\n        XOR     AL, SEG_INVERT\n        MOV     DX, P8255_PA\n        OUT     DX, AL              ; 送段码\n\n        INC     BX\n        AND     BX, 7\n        MOV     DISP_IDX, BX\n\n        POP     SI\n        POP     DX\n        POP     CX\n        POP     BX\n        POP     AX\n        RET\nDISP_NEXT ENDP\n\n        END     START\n\r\n"},{"id":"matrix","name":"实验三-6：8×8 点阵显示“接口技术”","note":"每字 1.8 秒循环，红色点阵。","wiring":{"out0Pc7":true,"matrixMode":true},"source":"﻿;=====================================================================\r\n; 实验三 任务6：8×8 LED 点阵红色循环显示“接口技术”四个字\r\n;---------------------------------------------------------------------\r\n; 接线（SHYL-WJ86 实验箱）：\r\n;   1. 地址译码 CS0（200H~20FH）  -> 8253/8254 的 /CS\r\n;   2. 8253 的 D0~D7、/RD、/WR、A0、A1 走板内系统总线，无需再接\r\n;   3. 1MHz 固定脉冲输出 -> CLK0\r\n;   4. GATE0 -> +5V（或接 K1 并置高）\r\n;   5. OUT0 -> 8255 PC7（1ms 方波，作为逐列扫描的节拍）\r\n;   6. 8255 基址 210H：A口=210H，B口=211H，C口=212H，控制口=213H\r\n;   7. 8255 PA7~PA0 -> 点阵行输入 R1~R8（PA7 接最上面一行 R1，\r\n;      PA0 接最下面一行 R8）；8255 PB0~PB7 -> 点阵列输入 C1~C8\r\n;      （PB0 接最左一列 C1，PB7 接最右一列 C8）。\r\n;      点阵红色列接 PB0~PB7；若是双色点阵，绿色列暂时不接或接低电平。\r\n;   8. 本代码按“行数据 1=亮、列选通 1=有效”编写。若点阵驱动反相，\r\n;      把行数据/列选通取反，或按文件末尾说明改接线。\r\n;---------------------------------------------------------------------\r\n; 显示原理：\r\n;   每个字 8 列，每列 1 字节（高位在上、低位在下）。\r\n;   逐列扫描：PA 送该列 8 位行数据，PB 送列选通（01H、02H、…、80H），\r\n;   每列保持 1ms，8 列共 8ms 扫完一遍（利用视觉暂留）。\r\n;   1.8s / 8ms = 225 遍，因此每个字扫描 225 遍后换下一个字。\r\n;   8253 计数器0：方式3，初值1000 -> 1kHz 方波（1ms 一个上升沿）。\r\n;   控制字：计数器0 = 36H。\r\n;=====================================================================\r\n\r\n        .8086\r\n        .MODEL SMALL\r\n        .STACK 100H\r\n\r\n;---- 端口地址 ----\r\nP8253_C0        EQU     0200H\r\nP8253_CTRL      EQU     0203H\r\nP8255_PA        EQU     0210H\r\nP8255_PB        EQU     0211H\r\nP8255_PC        EQU     0212H\r\nP8255_CTRL      EQU     0213H\r\n\r\n;---- 每个字扫描遍数：225 × 8ms = 1800ms = 1.8s ----\r\nFRAMES_PER_CHAR EQU     225\r\nCHARS           EQU     4\r\n\r\n;---- 点阵极性：0=高有效；若行/列为低有效，分别改为 0FFH ----\r\nROW_INVERT      EQU     0\r\nCOL_INVERT      EQU     0\r\n\r\n        .DATA\r\n;---- “接口技术”四个字的 8×8 点阵字模，每字 8 字节（每字节一列）----\r\nFONT    DB      022H,0FFH,052H,076H,023H,072H,052H,08AH    ; 接\r\n        DB      000H,000H,07EH,042H,042H,07EH,000H,000H    ; 口\r\n        DB      022H,072H,027H,0FAH,056H,023H,052H,08AH    ; 技\r\n        DB      008H,028H,07FH,008H,01CH,02AH,049H,008H    ; 术\r\n\r\n        .CODE\r\nSTART   PROC\r\n        MOV     AX, @DATA\r\n        MOV     DS, AX\r\n\r\n        ;---- 8255：A口、B口输出，C口输入（PC7 读 8253 OUT0）----\r\n        MOV     DX, P8255_CTRL\r\n        MOV     AL, 89H            ; 1000 1001B：A/B输出，C口输入\r\n        OUT     DX, AL\r\n\r\n        ;---- 8253 计数器0：方式3，初值1000，输出 1kHz 方波 ----\r\n        MOV     DX, P8253_CTRL\r\n        MOV     AL, 36H            ; 计数器0，方式3，先低后高，二进制\r\n        OUT     DX, AL\r\n\r\n        MOV     DX, P8253_C0\r\n        MOV     AX, 1000\r\n        OUT     DX, AL\r\n        MOV     AL, AH\r\n        OUT     DX, AL\r\n\r\n        ;---- 从第一个字开始循环 ----\r\n        LEA     SI, FONT\r\n        MOV     BP, CHARS\r\n\r\nNEXT_CHAR:\r\n        MOV     CX, FRAMES_PER_CHAR\r\n\r\nFRAME_LOOP:\r\n        MOV     BX, 8              ; 8 列\r\n        MOV     AH, 01H            ; 列选通初值：PB0 有效\r\n\r\nCOL_LOOP:\r\n        ;---- 行数据送 PA ----\r\n        MOV     AL, [SI]\r\n        XOR     AL, ROW_INVERT     ; 低电平点亮的点阵在此取反\r\n        MOV     DX, P8255_PA\r\n        OUT     DX, AL\r\n\r\n        ;---- 列选通送 PB ----\r\n        MOV     AL, AH\r\n        XOR     AL, COL_INVERT     ; 低电平选通的点阵在此取反\r\n        MOV     DX, P8255_PB\r\n        OUT     DX, AL\r\n\r\n        ;---- 该列保持 1ms ----\r\n        CALL    WAIT_1MS\r\n\r\n        SHL     AH, 1              ; 下一列：01H->02H->...->80H\r\n        INC     SI\r\n        DEC     BX\r\n        JNZ     COL_LOOP\r\n\r\n        ;---- 一帧结束，指针回到本字第一列 ----\r\n        SUB     SI, 8\r\n        LOOP    FRAME_LOOP\r\n\r\n        ;---- 本字显示 1.8s 结束，指向下一个字 ----\r\n        ADD     SI, 8\r\n        DEC     BP\r\n        JNZ     NEXT_CHAR\r\n\r\n        ;---- 四个字显示完，回到第一个字循环 ----\r\n        LEA     SI, FONT\r\n        MOV     BP, CHARS\r\n        JMP     NEXT_CHAR\r\nSTART   ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; WAIT_1MS：等待 PC7 上 1kHz 方波的一个上升沿（1ms）\r\n; 先等低电平，再等上升沿，保证每次调用跨过完整 1ms。\r\n;---------------------------------------------------------------------\r\nWAIT_1MS PROC\r\n        PUSH    DX\r\n        PUSH    AX\r\n        MOV     DX, P8255_PC\r\n\r\nWAIT_LOW:\r\n        IN      AL, DX\r\n        TEST    AL, 80H\r\n        JNZ     WAIT_LOW          ; 等待 PC7 变低\r\n\r\nWAIT_HIGH:\r\n        IN      AL, DX\r\n        TEST    AL, 80H\r\n        JZ      WAIT_HIGH         ; 等待 PC7 变高（上升沿）\r\n\r\n        POP     AX\r\n        POP     DX\r\n        RET\r\nWAIT_1MS ENDP\r\n\r\n\r\n\r\n;=====================================================================\r\n; 显示方向调整说明：\r\n;   1. 若整字左右相反：把列选通初值改为 80H，并把 SHL AH,1 改成\r\n;      SHR AH,1（即从 PB7 向 PB0 扫描）。\r\n;   2. 若整字上下相反：把 PA0~PA7 的接线顺序反过来，或把 FONT 中\r\n;      每个字节按位倒序（可用 BTR/移位程序预处理）。\r\n;   3. 若点阵为低电平点亮/低电平选通：把文件前面的 ROW_INVERT 和\r\n;      COL_INVERT 由 0 改为 0FFH；若只有行（或列）反相，只改对应一个。\r\n;=====================================================================\r\n\r\n        END     START\r\n\r\n"},{"id":"traffic","name":"实验三-5：8253 定时交通灯","note":"PA0~PA5 接交通灯（本模拟器显示在 L1~L8），绿 10 秒、黄 2 秒循环。","wiring":{"out0Clk1":true,"out1Pc0":true,"ledPort":"PA"},"source":"﻿;=====================================================================\r\n; 实验三 任务5：8253 定时实现交通信号灯控制\r\n;---------------------------------------------------------------------\r\n; 接线（SHYL-WJ86 实验箱）：\r\n;   1. 地址译码 CS0（200H~20FH）  -> 8253/8254 的 /CS\r\n;   2. 8253 的 D0~D7、/RD、/WR、A0、A1 走板内系统总线，无需再接\r\n;   3. 1MHz 固定脉冲输出 -> CLK0\r\n;   4. OUT0 -> CLK1\r\n;   5. GATE0、GATE1 -> +5V（或接 K1 并置高）\r\n;   6. 8255 基址 210H：A口=210H，B口=211H，C口=212H，控制口=213H\r\n;      （8255 的 /CS 接 210H~213H 译码输出；板内已固定则不用再接）\r\n;   7. 8255 PC0 <- 8253 OUT1（1Hz 方波，作为 1 秒基准）\r\n;   8. 8255 PA0~PA5 -> 交通灯 LED（或交通灯模块输入端）：\r\n;         PA0 = 南北红灯\r\n;         PA1 = 南北黄灯\r\n;         PA2 = 南北绿灯\r\n;         PA3 = 东西红灯\r\n;         PA4 = 东西黄灯\r\n;         PA5 = 东西绿灯\r\n;      本代码按“1 = 点亮”编写；若模块低电平点亮，见文件末尾说明。\r\n;---------------------------------------------------------------------\r\n; 定时：\r\n;   1MHz / 1000 = 1kHz         计数器0，方式3，初值1000\r\n;   1kHz / 1000 = 1Hz 方波     计数器1，方式3，初值1000\r\n;   软件查询 PC0 的下降沿，每检测到一次即 1 秒。\r\n; 相位：\r\n;   南北绿 + 东西红   10s\r\n;   南北黄 + 东西红    2s\r\n;   南北红 + 东西绿   10s\r\n;   南北红 + 东西黄    2s\r\n;   循环。修改 GREEN_TIME / YELLOW_TIME 即可改变配时。\r\n;=====================================================================\r\n\r\n        .8086\r\n        .MODEL SMALL\r\n        .STACK 100H\r\n\r\n;---- 端口地址 ----\r\nP8253_C0        EQU     0200H\r\nP8253_C1        EQU     0201H\r\nP8253_CTRL      EQU     0203H\r\nP8255_PA        EQU     0210H\r\nP8255_PB        EQU     0211H\r\nP8255_PC        EQU     0212H\r\nP8255_CTRL      EQU     0213H\r\n\r\n;---- 配时（单位：秒）----\r\nGREEN_TIME      EQU     10\r\nYELLOW_TIME     EQU     2\r\n\r\n;---- 灯位极性：0=高电平点亮；若模块低电平点亮，改为 0FFH ----\r\nLIGHT_INVERT    EQU     0\r\n\r\n;---- 交通灯图案：PA5~PA0 = 东西绿、东西黄、东西红、南北绿、南北黄、南北红 ----\r\nPAT_NS_G_EW_R   EQU     00001100B      ; PA2=1, PA3=1\r\nPAT_NS_Y_EW_R   EQU     00001010B      ; PA1=1, PA3=1\r\nPAT_NS_R_EW_G   EQU     00100001B      ; PA0=1, PA5=1\r\nPAT_NS_R_EW_Y   EQU     00010001B      ; PA0=1, PA4=1\r\n\r\n        .CODE\r\nSTART   PROC\r\n        ;---- 8255：A口、B口输出，C口输入 ----\r\n        MOV     DX, P8255_CTRL\r\n        MOV     AL, 89H            ; 1000 1001B：A/B输出，C口输入\r\n        OUT     DX, AL\r\n\r\n        ;---- 先熄灭全部灯 ----\r\n        MOV     DX, P8255_PA\r\n        MOV     AL, 00H\r\n        OUT     DX, AL\r\n        MOV     DX, P8255_PB\r\n        MOV     AL, 00H\r\n        OUT     DX, AL\r\n\r\n        ;---- 计数器0：1MHz / 1000 = 1kHz ----\r\n        MOV     DX, P8253_CTRL\r\n        MOV     AL, 36H            ; 计数器0，方式3，先低后高，二进制\r\n        OUT     DX, AL\r\n\r\n        MOV     DX, P8253_C0\r\n        MOV     AX, 1000\r\n        OUT     DX, AL\r\n        MOV     AL, AH\r\n        OUT     DX, AL\r\n\r\n        ;---- 计数器1：1kHz / 1000 = 1Hz 方波 ----\r\n        MOV     DX, P8253_CTRL\r\n        MOV     AL, 76H            ; 计数器1，方式3，先低后高，二进制\r\n        OUT     DX, AL\r\n\r\n        MOV     DX, P8253_C1\r\n        MOV     AX, 1000\r\n        OUT     DX, AL\r\n        MOV     AL, AH\r\n        OUT     DX, AL\r\n\r\n        ;---- 与 1Hz 方波同步，保证第一相位从整秒开始 ----\r\n        CALL    WAIT_1S\r\n\r\nMAIN_LOOP:\r\n        ;---- 南北绿，东西红 ----\r\n        MOV     AL, PAT_NS_G_EW_R\r\n        CALL    SET_LIGHTS\r\n        MOV     CX, GREEN_TIME\r\n        CALL    DELAY_SECS\r\n\r\n        ;---- 南北黄，东西红 ----\r\n        MOV     AL, PAT_NS_Y_EW_R\r\n        CALL    SET_LIGHTS\r\n        MOV     CX, YELLOW_TIME\r\n        CALL    DELAY_SECS\r\n\r\n        ;---- 南北红，东西绿 ----\r\n        MOV     AL, PAT_NS_R_EW_G\r\n        CALL    SET_LIGHTS\r\n        MOV     CX, GREEN_TIME\r\n        CALL    DELAY_SECS\r\n\r\n        ;---- 南北红，东西黄 ----\r\n        MOV     AL, PAT_NS_R_EW_Y\r\n        CALL    SET_LIGHTS\r\n        MOV     CX, YELLOW_TIME\r\n        CALL    DELAY_SECS\r\n\r\n        JMP     MAIN_LOOP\r\nSTART   ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; SET_LIGHTS：把 AL 中的灯位图案送 8255 A 口\r\n;---------------------------------------------------------------------\r\nSET_LIGHTS PROC\r\n        XOR     AL, LIGHT_INVERT   ; 低电平点亮的模块在此自动取反\r\n        MOV     DX, P8255_PA\r\n        OUT     DX, AL\r\n        RET\r\nSET_LIGHTS ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; WAIT_1S：等待 PC0 上 1Hz 方波的一个下降沿（即 1 秒）\r\n; 进入时若 PC0 为低，会先等它变高，再等下降沿，保证对齐整秒。\r\n;---------------------------------------------------------------------\r\nWAIT_1S PROC\r\n        PUSH    DX\r\n        PUSH    AX\r\n        MOV     DX, P8255_PC\r\n\r\nWAIT_HIGH:\r\n        IN      AL, DX\r\n        TEST    AL, 01H\r\n        JZ      WAIT_HIGH          ; 等待 PC0 变高\r\n\r\nWAIT_LOW:\r\n        IN      AL, DX\r\n        TEST    AL, 01H\r\n        JNZ     WAIT_LOW          ; 等待 PC0 变低（下降沿）\r\n\r\n        POP     AX\r\n        POP     DX\r\n        RET\r\nWAIT_1S ENDP\r\n\r\n;---------------------------------------------------------------------\r\n; DELAY_SECS：延时 CX 秒；每次调用 WAIT_1S 正好跨 1 个下降沿\r\n;---------------------------------------------------------------------\r\nDELAY_SECS PROC\r\n        PUSH    CX\r\nDELAY_LOOP:\r\n        CALL    WAIT_1S\r\n        LOOP    DELAY_LOOP\r\n        POP     CX\r\n        RET\r\nDELAY_SECS ENDP\r\n\r\n\r\n\r\n;=====================================================================\r\n; 说明：\r\n;   若实验箱的 LED/交通灯模块是“低电平点亮”，只需把文件前面的\r\n;   LIGHT_INVERT 由 0 改成 0FFH，SET_LIGHTS 会自动把图案取反，\r\n;   不必逐个修改 PAT_xxx 常数。\r\n;=====================================================================\r\n\r\n        END     START\r\n\r\n"}];
